const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createTradeGate(run,changed=()=>{}){
  let pending=false;
  return async args=>{
    if(pending)return {ok:false,ignored:true};
    pending=true;changed(true,args);
    try{return await run(args);}finally{pending=false;changed(false,args);}
  };
}
export function connectOnline({receive,toast,tradeState}){
  const tradeCommand=createTradeGate(args=>commandNow('trade',args),tradeState);
  let confirming=false;let room=null,connected=false,busy=false,playing=false,menuKey='',winnerShown=false,endingShown=false,requestId=0,appliedId=0,mutating=false;
  const menu=document.createElement('section');menu.id='online-menu';menu.setAttribute('aria-label','Главное меню');document.body.appendChild(menu);
  const status=document.createElement('div');status.id='network';status.innerHTML='<span>Подключение…</span><button id="room-button">Комната</button>';document.body.appendChild(status);
  const $=s=>document.querySelector(s);
  $('#pause').disabled=true;document.querySelectorAll('[data-speed]').forEach(b=>b.disabled=true);
  const timeBox=document.createElement('aside');timeBox.id='time-vote';timeBox.hidden=true;document.body.append(timeBox);
  function updateStatus(){status.querySelector('span').textContent=connected?(room?`● ${room.code} · людей ${room.players.filter(p=>!p.bot).length} · ботов ${(room.phase==='lobby'?room.botCount:room.players.filter(p=>p.bot).length)}`:'● Сервер доступен'):'○ Переподключение…';status.classList.toggle('offline',!connected);}
  function showMenu(){
    menu.hidden=false;document.body.classList.add('in-menu');
    const key=room?JSON.stringify([room.code,room.phase,room.players,room.host,room.map,room.botCount,room.botDifficulties,room.closed,room.botSlots,room.seed,room.solo]):'main';if(menuKey===key)return;menuKey=key;
    if(room&&room.state?.eliminated){
      const defeat=room.state.defeat;menu.innerHTML='<div class="menu-card"><div class="eyebrow">'+(room.state.eliminated?'ВСЕ ВЛАДЕНИЯ ПОТЕРЯНЫ':'ПОБЕДА ЗАПИСАНА · МИР ПРОДОЛЖАЕТСЯ')+'</div><h1>'+ (room.state.eliminated?'Ваше правление завершено':esc(room.winner.name))+'</h1><p class="menu-intro">'+(defeat?esc(defeat.attacker)+' захватил '+esc(defeat.place)+'. Сила атакующего войска: '+defeat.force+', ваша оборона: '+defeat.defense+'.':room.winner?esc(room.winner.type):'Столица захвачена противником.')+'</p><p>После потери всех поселений приказы недоступны. Мир продолжает жить: боты строят и воюют.  Можно наблюдать за картой или начать новую партию.</p><button class="secondary full" id="back-game">Наблюдать за партией</button><button class="primary full" id="leave">Выйти в главное меню</button></div>';return;
    }
    if(room){
      const running=room.phase==='playing';
      if(running){menu.innerHTML=`<div class="menu-card match-menu"><div class="eyebrow">МЕНЮ МАТЧА · ${room.code}</div><h1>${esc(room.title)}</h1><p>${room.players.map(p=>esc(p.name)+(p.bot?' · бот':'')).join(' / ')}</p><button class="primary full" id="back-game">Продолжить</button><button class="secondary full" id="match-settings">Настройки звука</button><button class="secondary full" id="leave-match">Покинуть матч</button><button class="sub-action" id="main-menu">Выйти в главное меню</button><p id="menu-error" role="alert"></p></div>`;return;}
      menu.innerHTML=`<div class="menu-card lobby-card"><div class="eyebrow">ЗАЛ ПРАВИТЕЛЕЙ · КОД ${room.code}</div><h1>${esc(room.title)}</h1><p class="menu-intro">${room.players.length+room.botCount} / 4 правителя · ${room.solo?'Одиночная игра':'Сетевая игра'} · все начинают с равными ресурсами</p><div class="lobby-grid"><div><h2>Игроки и свободные места</h2><div class="lobby-list">${Array.from({length:4},(_,i)=>{const p=room.players.find(p=>p.slot===i),bot=room.botSlots.indexOf(i),closed=room.closed?.includes(i);return p?`<div><span class="player-avatar">♛</span><span>${esc(p.name)}<small>Слот ${i+1} · ${p.ready?'Готов':'Не готов'}</small></span>${room.host&&p.id!==room.self?`<button class="sub-action" data-kick="${p.id}">Выгнать</button>`:''}</div>`:bot>=0&&bot<room.botCount?`<div><span class="player-avatar">⚔</span><span>Бот · слот ${i+1}<small>Те же ресурсы и правила, что у игрока</small></span><select data-bot-level="${bot}" aria-label="Сложность бота ${bot+1}" ${room.host?'':'disabled'}>${[['easy','Слабый'],['medium','Средний'],['hard','Сильный']].map(([v,n])=>`<option value="${v}" ${room.botDifficulties[bot]===v?'selected':''}>${n}</option>`).join('')}</select>${room.host?` <button data-remove-bot="${bot}">−</button>`:''}</div>`:`<div><span>Слот ${i+1}<small>${closed?'Закрыт':'Свободен · пригласите друга'}</small></span>${room.host?`${closed?'': '<button class="secondary" data-add-bot>+ Бот</button>'}<button class="sub-action" data-slot="${i}">${closed?'Открыть':'Закрыть'}</button>`:''}</div>`;}).join('')}</div><button class="secondary" id="invite">Скопировать приглашение</button></div><div class="lobby-settings"><h2>Параметры матча</h2><label>Режим<select id="lobby-mode" ${room.host?'':'disabled'}><option value="online" ${!room.solo?'selected':''}>Сетевая игра</option><option value="solo" ${room.solo?'selected':''}>Одиночная игра</option></select></label><label>Карта<select id="lobby-map" ${room.host?'':'disabled'}>${[['valley','Речная долина'],['forest','Лесное пограничье'],['hills','Каменные холмы']].map(([v,n])=>`<option value="${v}" ${room.map===v?'selected':''}>${n}</option>`).join('')}</select></label><p>Сбалансированные стартовые точки. Места правителей распределяются случайно. Две общие деревни на севере и юге; центр даёт дополнительный доход.</p><p class="muted">Вариант мира: ${room.seed}. Декор и парные территории меняются при создании комнаты.</p>${room.host?'<button class="secondary" data-reroll>Новый вариант мира</button>':''}<p>Поражение: потеря всех поселений.<br>Оккупация: доход 50% на 60 секунд.<br>Стартовая защита от ботов: 5 минут.</p></div></div><div class="lobby-actions"><button class="secondary" id="ready">${room.players.find(p=>p.id===room.self)?.ready?'Не готов':'Готов'}</button>${room.host?'<button class="primary" id="start">Запустить матч</button>':'<p>Ждём запуска создателем комнаты</p>'}<button class="danger" id="leave">Покинуть комнату</button></div><p id="menu-error" role="alert"></p></div>`;

    }else menu.innerHTML=`<div class="menu-card"><div class="eyebrow">3D СТРАТЕГИЯ В РЕАЛЬНОМ ВРЕМЕНИ</div><div class="menu-crown">♛</div><h1>Королевства</h1><p class="menu-intro">Постройте державу. Найдите союзников.<br>Разделите один мир с друзьями.</p><label>Имя правителя<input id="nickname" maxlength="24" autocomplete="nickname" placeholder="Например, Торвальд" value="${esc(localStorage.getItem('kingdoms-nickname')||'')}"></label><label>Карта<select id="map-choice"><option value="valley">Речная долина · +25 еды/мин</option><option value="forest">Лесное пограничье · +25 дерева/мин</option><option value="hills">Каменные холмы · +25 камня/мин</option></select></label><p class="muted">Первые 5 минут боты не нападают на державы игроков. Стройте экономику и оставляйте защитников в столице.</p><label>Боты в партии<select id="bot-count"><option value="1">1 соперник</option><option value="2">2 соперника</option><option value="3">3 соперника</option><option value="0" selected>Без ботов · только друзья</option></select></label><button class="primary full" id="solo">Одиночная игра с ботами</button><button class="secondary full" id="create">Создать сетевую игру</button><div class="join-row"><input id="room-code" maxlength="6" placeholder="Код комнаты" aria-label="Код комнаты" value="${esc(new URLSearchParams(location.search).get('room')||'')}"><button class="secondary" id="join">Войти</button></div><div class="menu-foot"><span class="online-dot"></span> До 4 правителей · вход без регистрации<br>Все решения и боты рассчитываются сервером.</div><p id="menu-error" role="alert"></p></div>`;
  }
  function hideMenu(){confirming=false;menu.hidden=true;document.body.classList.remove('in-menu');}
  function apply(next,id=++requestId){if(id<appliedId)return;if(next?.code===room?.code&&next?.state&&room?.state&&next.state.time<room.state.time)return;appliedId=id;room=next;connected=true;updateStatus();if(!room){if(playing){sessionStorage.setItem('kingdoms-notice','Сервер перезапустился или комната закрыта. Предыдущая партия завершена. Создайте новую.');location.reload();return;}showMenu();return;}
    if(room.phase==='lobby'){showMenu();return;}
    if(!playing){playing=true;hideMenu();}
    receive(room.state,room);
    $('#pause').disabled=room.state.eliminated;document.querySelectorAll('[data-speed]').forEach(b=>{b.disabled=room.state.eliminated;b.title=room.solo?'Скорость вашей одиночной игры':'Согласие всех игроков; 1× можно вернуть сразу';});
    const vote=room.timeVote;if($('#drawer').open)$('#drawer .drawer-shell').prepend(timeBox);else document.body.append(timeBox);timeBox.hidden=!vote||room.state.eliminated;
    if(vote){timeBox.innerHTML='<strong>Общее время: '+(vote.speed===0?'пауза на 60 секунд':vote.speed+'×')+'</strong><p>Нужно согласие всех. Ещё '+Math.ceil(vote.end-room.wallTime)+' сек. Предложения раз в 2 минуты. Любой игрок может вернуть 1×.</p>'+ (vote.votes[room.self]?'<p>Вы согласились · ожидаем остальных</p>':'<button class="primary" data-time-yes>Согласен</button> <button class="secondary" data-time-no>Отклонить</button>');}
    if(room.state.speed===0&&!room.solo)status.querySelector('span').textContent+=' · Пауза (не дольше минуты)';
    document.querySelector('.profile').innerHTML=`<span class="shield-mark">♛</span><span>${esc(room.players.find(p=>p.id===room.self)?.name||'Гость')}<small>${room.state.eliminated?'Наблюдатель · столица потеряна':room.state.places.find(p=>p.id===room.state.home)?.name}</small></span>`;
    if(room.state.eliminated&&!endingShown){endingShown=true;$('#drawer').close();menuKey='';showMenu();}
    if(room.state.eliminated){$('#objective').innerHTML='<div class="panel-kicker">СТОЛИЦА ПОТЕРЯНА</div><h3>Ваше правление завершено</h3><p>Можно наблюдать за остальными державами.</p>';}
    if(room.winner&&!room.state.eliminated){$('#objective').innerHTML=`<div class="panel-kicker">ПОБЕДА ЗАПИСАНА · МИР ПРОДОЛЖАЕТСЯ</div><h3>${esc(room.winner.name)}</h3><p>${room.winner.type}</p>`;if(!winnerShown){toast(room.winner.type+' — '+room.winner.name);winnerShown=true;}}
    if(!menu.hidden&&!confirming)showMenu();
  }
  async function api(path,data={}){const id=++requestId;const res=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),signal:AbortSignal.timeout(15000)});const r=await res.json();if(!res.ok||r.ok===false)throw new Error(r.message||'Ошибка сервера');if('room'in r)apply(r.room,id);return r;}
  async function leave(){playing=false;await api('leave');location.href=location.pathname;}
  async function command(type,args={}){return type==='trade'?tradeCommand(args):commandNow(type,args);}
  async function commandNow(type,args={}){if(room?.state?.eliminated)return {ok:false,message:'Столица потеряна: приказы недоступны. Начните новую партию.'};if(busy)return {ok:false,message:'Предыдущий приказ ещё выполняется'};if(!connected||!playing)return {ok:false,message:'Связь с сервером потеряна. Переподключаемся…'};busy=true;mutating=true;try{return await api('command',{id:crypto.randomUUID(),type,args});}catch(e){return {ok:false,message:e.message};}finally{busy=false;mutating=false;}}
  async function poll(){const id=++requestId;try{const res=await fetch('/api/state',{cache:'no-store',signal:AbortSignal.timeout(10000)});if(!res.ok)throw new Error('Network');const next=(await res.json()).room;if(!mutating)apply(next,id);}catch(e){if(id>=appliedId){connected=false;updateStatus();}}setTimeout(poll,500);}
  document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;
    if(b.hasAttribute('data-time-yes')||b.hasAttribute('data-time-no')){const r=await command('time-vote',{accept:b.hasAttribute('data-time-yes')});toast(r.message,!r.ok);return;}
    if(b.id==='leave-match'||b.id==='main-menu'){menu.innerHTML='<div class="menu-card"><h1>Покинуть матч?</h1><p>Вы завершите свою сессию. Другие правители продолжат играть.</p><button class="danger full" id="confirm-leave">Да, покинуть матч</button><button class="secondary full" id="back-game">Отмена</button></div>';confirming=true;return;}
    if(b.id==='confirm-leave'){await leave();return;}
    if(b.id==='match-settings'){document.querySelector('#audio-toggle')?.click();toast('Звук переключён');return;}
    if(b.id==='ready'||b.hasAttribute('data-add-bot')||b.hasAttribute('data-remove-bot')||b.dataset.slot||b.dataset.kick||b.hasAttribute('data-reroll')){try{await api('lobby',b.id==='ready'?{action:'ready'}:b.dataset.kick?{action:'kick',id:b.dataset.kick}:b.dataset.slot?{action:'slot',slot:Number(b.dataset.slot)}:b.hasAttribute('data-reroll')?{action:'seed'}:{action:'bots',count:room.botCount+(b.hasAttribute('data-add-bot')?1:-1),index:Number(b.dataset.removeBot)});}catch(e){toast(e.message,true);}return;}
    if(b.id==='room-button'){$('#drawer').close();showMenu();return;}
    if(b.id==='back-game'){hideMenu();return;}
    if(b.id==='invite'){try{await navigator.clipboard.writeText(location.origin+location.pathname+'?room='+room.code);toast('Приглашение скопировано');}catch{toast('Код комнаты: '+room.code);}return;}
    if(b.dataset.accept||b.dataset.reject){const r=await command(b.dataset.accept?'accept':'reject',{id:b.dataset.accept||b.dataset.reject});toast(r.message||'Готово',!r.ok);return;}
    if(!['solo','create','join','start','leave'].includes(b.id))return;
    b.disabled=true;try{const name=$('#nickname')?.value||'Гость';if($('#nickname'))localStorage.setItem('kingdoms-nickname',name);let r;
      if(['solo','create'].includes(b.id))r=await api('create',{name,bots:b.id==='solo'?Math.max(1,Number($('#bot-count').value)):Number($('#bot-count').value),solo:b.id==='solo',map:$('#map-choice').value});
      if(b.id==='join')r=await api('join',{name,code:$('#room-code').value});if(b.id==='start')r=await api('start');if(b.id==='leave'){await leave();return;}
      if(r&&!r.ok){$('#menu-error').textContent=r.message;toast(r.message,true);}
    }catch(err){if($('#menu-error'))$('#menu-error').textContent=err.message;}finally{b.disabled=false;}
  });
  document.addEventListener('change',async e=>{if(e.target.id==='lobby-map'||e.target.id==='lobby-mode'||e.target.hasAttribute('data-bot-level'))try{await api('lobby',e.target.id==='lobby-map'?{action:'map',value:e.target.value}:e.target.id==='lobby-mode'?{action:'mode',value:e.target.value}:{action:'difficulty',index:Number(e.target.dataset.botLevel),value:e.target.value});}catch(err){menuKey='';showMenu();toast(err.message,true);}});
  document.addEventListener('keydown',e=>{if(e.key!=='Escape'||!playing||document.querySelector('#drawer').open)return;e.preventDefault();if(menu.hidden){menuKey='';showMenu();}else hideMenu();});
  const treaty={peace:'мир',pact:'пакт о ненападении',alliance:'союз',trade:'торговый путь',aid:'военную помощь'};
  showMenu();const notice=sessionStorage.getItem('kingdoms-notice');if(notice){$('#menu-error').textContent=notice;sessionStorage.removeItem('kingdoms-notice');}poll();
  return {command,leave,status:()=>({connected,busy,ended:!!room?.state?.eliminated}),offersHTML:()=>room?.offers?.map(o=>`<article class="item-card"><h3>${esc(o.name)} предлагает ${treaty[o.action]}</h3><p>Ещё ${Math.ceil(o.end-room.state.time)} сек.</p><div class="actions"><button class="primary" data-accept="${o.id}">Принять</button><button class="secondary" data-reject="${o.id}">Отклонить</button></div></article>`).join('')||''};
}
